"""M1-T18 intent: annualize scales daily volatility over 252 trading days (RISK-03, TC-06)."""

from __future__ import annotations

import pytest

from risk import Returns, VolSeries, annualize


def _returns(data: dict) -> Returns:
    return Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def _vol(data: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(data["returns"]),
        window=data["window"],
        annualized=data["annualized"],
        values={t: tuple(v) for t, v in data["values"].items()},
    )


@pytest.mark.intent
def test_tc06_each_value_scaled_and_gaps_kept(golden):
    inp, expected = golden("risk", "TC-06")
    vol = _vol(inp["vol"])
    tol = expected["tol"]

    out = annualize(vol)

    assert out.annualized is expected["annualized"]
    assert set(out.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = out.values[ticker]
        assert len(got) == len(want)
        for g, w in zip(got, want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g == pytest.approx(w, abs=tol)


@pytest.mark.intent
def test_tc06_keeps_returns_and_window(golden):
    inp, _ = golden("risk", "TC-06")
    vol = _vol(inp["vol"])

    out = annualize(vol)

    assert out.returns == vol.returns
    assert out.window == vol.window


@pytest.mark.intent
def test_annualizing_an_annualized_series_is_a_value_error(contract_sample):
    vol = _vol(contract_sample("risk.VolSeries"))
    assert vol.annualized is True

    with pytest.raises(ValueError, match="annualized"):
        annualize(vol)


@pytest.mark.intent
def test_annualizing_twice_is_a_value_error(golden):
    inp, _ = golden("risk", "TC-06")
    once = annualize(_vol(inp["vol"]))

    with pytest.raises(ValueError, match="annualized"):
        annualize(once)

